questionvariables.text:
stack_include_contrib("prooflib.mac");
xm : rand([5,6,7,8]);
ym : rand([7,8,9,10]);
dx : rand([3,4]);
dy : rand([5,6]);
sgn : rand([-1,1]);
ax : xm - dx; ay : ym - sgn*dy;
bx : xm + dx; by : ym + sgn*dy;
slope : sgn*dy/dx;
xmaxw : bx + 2;
ymaxw : max(ay, by, ym) + 3;
mean_str : sconcat("Plot the mean point \\((", xm, ",\\ ", ym, ")\\) and mark it clearly.");
proof_steps : [
 ["mean", mean_str],
 ["ruler", "Lay a transparent ruler across the grid."],
 ["pivot", "Pivot the ruler through the mean point so the remaining points are balanced evenly above and below the line."],
 ["draw", "Draw a single, clean, straight line right across the grid."]
];
proof_steps : random_permutation(proof_steps);
ta : proof("mean","ruler","pivot","draw");
GradOpts : [[optPos, is(sgn=1), "Positive"], [optNeg, is(sgn=-1), "Negative"]];
RelOpts  : [[optPosR, is(sgn=1), "Positive relationship (as x increases, y increases)"], [optNegR, is(sgn=-1), "Negative relationship (as x increases, y decreases)"]];
gradCorrect : if is(sgn=1) then optPos else optNeg;
relCorrect  : if is(sgn=1) then optPosR else optNegR;
